func (q *Queries) ListUnscored(ctx context.Context, limit int32) ([]ListUnscoredRow, error) {
	rows, err := q.db.Query(ctx, listUnscored, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUnscoredRow{}
	for rows.Next() {
		var i ListUnscoredRow
		if err := rows.Scan(&i.ID, &i.UserID, &i.CustomerID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const recomputeInvoiceStatus = `-- name: RecomputeInvoiceStatus :one
WITH paid AS (
    SELECT COALESCE(SUM(amount), 0)::BIGINT AS total
    FROM payments
    WHERE invoice_id = $1
)
UPDATE invoices
SET
    paid_amount = paid.total,
    status = CASE
        WHEN paid.total = 0           THEN 'unpaid'
        WHEN paid.total < invoices.amount THEN 'partial'
        ELSE                               'paid'
    END,
    paid_at = CASE
        WHEN paid.total >= invoices.amount AND paid_at IS NULL THEN now()
        ELSE paid_at
    END,
    updated_at = now()
FROM paid
WHERE invoices.id = $1
  AND invoices.user_id = $2
RETURNING invoices.id, invoices.user_id, invoices.customer_id, invoices.amount, invoices.currency, invoices.paid_amount, invoices.paid_at, invoices.description, invoices.due_date, invoices.status, invoices.source, invoices.photo_url, invoices.external_id, invoices.issued_at, invoices.items, invoices.collection_state, invoices.last_contacted_at, invoices.last_response_at, invoices.follow_up_count, invoices.confidence_score, invoices.confidence_factors, invoices.outcome_text, invoices.outcome_timeframe, invoices.confidence_computed_at, invoices.created_at, invoices.updated_at, invoices.promised_at
`

